import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

const canvas=document.querySelector('#game');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.28;
const scene=new THREE.Scene();scene.background=new THREE.Color(0x07121d);scene.fog=new THREE.FogExp2(0x07121d,.025);
const camera=new THREE.PerspectiveCamera(43,1,.1,120);camera.position.set(0,17,22);
const clock=new THREE.Clock(),raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2(),floorPlane=new THREE.Plane(new THREE.Vector3(0,1,0),0),aimPoint=new THREE.Vector3();
const world=new THREE.Group();scene.add(world);
const mat=(color,metalness=0,roughness=.5,emissive=0,emissiveIntensity=0)=>new THREE.MeshStandardMaterial({color,metalness,roughness,emissive,emissiveIntensity});
const mats={floor:mat(0x182633,.38,.72),floorDark:mat(0x0b1722,.3,.75),steel:mat(0x243542,.75,.32),steel2:mat(0x374b58,.65,.3),cyan:mat(0x49e6f4,.3,.25,0x27dff4,2.6),red:mat(0xff5472,.25,.3,0xff264f,2),amber:mat(0xffb75a,.3,.3,0xff9b35,2),black:mat(0x09131d,.55,.3),white:mat(0xdce9ec,.3,.4)};
scene.add(new THREE.HemisphereLight(0x9bd5ed,0x18212a,2.1));const key=new THREE.DirectionalLight(0xb7e5ff,3.2);key.position.set(-7,16,8);key.castShadow=true;key.shadow.mapSize.set(2048,2048);key.shadow.camera.left=-22;key.shadow.camera.right=22;key.shadow.camera.top=22;key.shadow.camera.bottom=-22;scene.add(key);
const cyanLight=new THREE.PointLight(0x1cdcf5,36,19,2);cyanLight.position.set(-9,5,-4);scene.add(cyanLight);const redLight=new THREE.PointLight(0xff3d62,32,18,2);redLight.position.set(9,5,4);scene.add(redLight);
function box(parent,x,y,z,sx,sy,sz,material,cast=true,receive=true){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material);m.position.set(x,y,z);m.castShadow=cast;m.receiveShadow=receive;parent.add(m);return m}
function cylinder(parent,x,y,z,r1,r2,h,material,segments=12){const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,segments),material);m.position.set(x,y,z);m.castShadow=true;parent.add(m);return m}
function ring(parent,x,y,z,r,t,material){const m=new THREE.Mesh(new THREE.TorusGeometry(r,t,8,64),material);m.rotation.x=Math.PI/2;m.position.set(x,y,z);parent.add(m);return m}
// Foundry arena shell and gridded deck
box(world,0,-.52,0,40,.9,34,mats.floorDark,false,true);box(world,0,-.04,0,29,.18,25,mats.floor,false,true);
for(let x=-13;x<=13;x+=2)box(world,x,.058,0,.035,.012,24,x%4===0?mat(0x304350):mat(0x253743),false,false);
for(let z=-11;z<=11;z+=2)box(world,0,.06,z,28,.012,.035,mat(0x293d49),false,false);
// glowing map boundary strips
for(const [x,z,sx,sz] of [[0,-12.45,29,.09],[0,12.45,29,.09],[-14.45,0,.09,25],[14.45,0,.09,25]])box(world,x,.12,z,sx,.055,sz,mats.cyan,false,false);
for(let i=0;i<4;i++){const x=i<2?-14.45:14.45,z=i%2===0?-12.45:12.45;cylinder(world,x,1.2,z,.24,.31,2.4,mats.steel2,8);cylinder(world,x,2.05,z,.31,.31,.09,mats.cyan,8);}
// perimeter industrial walls and illuminated ribs
for(const side of [-1,1]){box(world,0,1.15,side*13,29,2.3,.55,mats.steel);for(let x=-13;x<=13;x+=3.25){box(world,x,1.25,side*12.68,.17,2.5,.15,mats.steel2);box(world,x,2.45,side*12.63,.18,.07,.07,side<0?mats.cyan:mats.red,false,false)}}
for(const side of [-1,1]){box(world,side*15,1.15,0,.55,2.3,25,mats.steel);for(let z=-11;z<=11;z+=3.2){box(world,side*14.68,1.25,z,.15,2.5,.18,mats.steel2);box(world,side*14.63,2.45,z,.07,.07,.18,side<0?mats.cyan:mats.red,false,false)}}
// industrial stacks beyond arena
for(let i=0;i<12;i++){let x=-16+(i%6)*6.4,z=-17-Math.floor(i/6)*3;const h=2+Math.random()*4;box(world,x,h/2,z,2.4,h,1.6,i%3?mats.black:mats.steel);box(world,x,h+.08,z,2.5,.12,1.7,i%2?mats.cyan:mats.red,false,false)}
// cover modules, crates and power cores
const obstacles=[];
function cover(x,z,w,d,h,accent){const g=new THREE.Group();g.position.set(x,0,z);world.add(g);box(g,0,h/2,0,w,h,d,mats.steel);box(g,0,h+.04,0,w+.12,.09,d+.12,accent,false,false);box(g,0,h*.64,d/2+.012,w*.72,.16,.03,mats.steel2,false,false);obstacles.push({x,z,r:Math.max(w,d)*.58});return g}
cover(-5.3,-4.4,3.8,1.2,1.2,mats.cyan);cover(5.2,4.3,3.8,1.2,1.2,mats.red);cover(-6.3,4.8,1.3,2.8,1.4,mats.cyan);cover(6.3,-4.8,1.3,2.8,1.4,mats.red);cover(0,-7.2,3.2,1.05,1,mats.amber);cover(0,7.2,3.2,1.05,1,mats.amber);
for(const [x,z,c] of [[-9,0,mats.cyan],[9,0,mats.red]]){cylinder(world,x,.45,z,.62,.62,.9,mats.steel2,10);cylinder(world,x,.96,z,.49,.49,.12,c,10);cylinder(world,x,1.25,z,.16,.16,.46,mats.white,8);ring(world,x,1.05,z,.72,.035,c)}
// decorative hazard marks
for(let i=-1;i<=1;i+=2){for(let j=0;j<4;j++){const x=i*(2.5+j*.35),z=i*2.7;box(world,x,.075,z,.13,.025,1.5,mats.amber,false,false)}}
// atmospheric floating sparks
const particles=new THREE.Group();world.add(particles);for(let i=0;i<85;i++){let p=new THREE.Mesh(new THREE.SphereGeometry(.025+Math.random()*.025,5,5),i%3?mats.cyan:mats.amber);p.position.set((Math.random()-.5)*27,.3+Math.random()*5,(Math.random()-.5)*23);p.userData={phase:Math.random()*6,speed:.3+Math.random()*.5};particles.add(p)}

function createHero(type,team){const root=new THREE.Group();const isVolt=type==='volt',color=team==='player'?mats.cyan:mats.red,accent=(isVolt?mats.cyan:mats.amber);world.add(root);const model=new THREE.Group();root.add(model);
  cylinder(model,0,.12,0,.42,.48,.2,color,10);cylinder(model,0,.23,0,.31,.34,.06,mats.white,10);
  // legs and boots
  for(const s of [-1,1]){const leg=box(model,s*.2,.57,0,.24,.67,.29,mats.steel2);leg.rotation.x=-.04;box(model,s*.2,.22,.11,.29,.2,.4,mats.black);box(model,s*.2,.47,-.02,.29,.12,.34,accent)}
  // torso armor
  const torso=box(model,0,1.16,0,.83,.88,.48,color);torso.rotation.x=-.04;box(model,0,1.32,.259,.53,.42,.06,mats.steel2);box(model,0,1.34,.3,.14,.12,.04,accent,false,false);box(model,0,1.78,0,.55,.18,.48,mats.black);
  for(const s of [-1,1]){const shoulder=cylinder(model,s*.52,1.52,0,.23,.27,.25,accent,8);shoulder.rotation.z=Math.PI/2;const arm=box(model,s*.59,1.12,.02,.23,.6,.3,mats.steel2);arm.rotation.z=s*.12;box(model,s*.64,.83,.1,.24,.17,.34,mats.black)}
  // helmet with luminous visor
  cylinder(model,0,1.98,0,.31,.33,.37,mats.steel2,10);box(model,0,2.01,.26,.4,.15,.1,accent,false,false);box(model,0,1.78,.07,.37,.11,.4,mats.black);
  // back thruster
  box(model,0,1.23,-.33,.5,.68,.22,mats.black);for(const s of [-1,1]){cylinder(model,s*.18,.97,-.48,.105,.13,.26,accent,8);box(model,s*.18,1.43,-.46,.12,.24,.12,mats.white)}
  // rifle held forward
  const gun=new THREE.Group();gun.position.set(.35,1.15,.42);model.add(gun);box(gun,.06,0,.04,.22,.22,.68,mats.black);box(gun,.06,.02,.29,.1,.1,.4,accent,false,false);box(gun,.06,.05,.44,.11,.11,.17,mats.white);box(gun,-.09,-.15,-.06,.08,.23,.13,mats.steel2);
  const shadow=new THREE.Mesh(new THREE.CircleGeometry(.65,20),new THREE.MeshBasicMaterial({color:0x02070c,transparent:true,opacity:.6,depthWrite:false}));shadow.rotation.x=-Math.PI/2;shadow.position.y=.075;root.add(shadow);
  const glow=new THREE.PointLight(team==='player'?0x31e6ff:0xff385e,2.8,3,2);glow.position.set(0,1.25,0);root.add(glow);
  root.userData={model,gun,type,team,health:200,maxHealth:200,alive:true,speed:isVolt?5.4:4.7,fireWait:0,dashWait:0,pulseWait:0,ult:0,walk:0,hitFlash:0};return root;
}
let player=null,enemy=null,heroChoice='volt',started=false,paused=false,finished=false,round=1,scorePlayer=0,scoreEnemy=0,roundTime=120,ammo=24,reload=0,fireHeld=false,keys={},joy={x:0,y:0,active:false},mobile=false,lastShot=0,enemyShot=0,toastTimer=0,hitTimer=0,ultTimer=0;
const projectiles=[],effects=[];
function makeProjectile(pos,dir,team,damage=20,speed=22){const group=new THREE.Group();scene.add(group);const core=new THREE.Mesh(new THREE.SphereGeometry(.1,8,8),team==='player'?mats.cyan:mats.red);group.add(core);const light=new THREE.PointLight(team==='player'?0x48eaff:0xff385e,2,3);group.add(light);group.position.copy(pos);const trail=new THREE.Mesh(new THREE.CylinderGeometry(.025,.055,.48,6),team==='player'?mats.cyan:mats.red);trail.rotation.x=Math.PI/2;trail.position.z=-.22;group.add(trail);projectiles.push({obj:group,dir:dir.clone().normalize(),team,damage,speed,life:2});}
function burst(position,color=0x5deeff,count=9){for(let i=0;i<count;i++){const m=new THREE.Mesh(new THREE.SphereGeometry(.035+Math.random()*.035,5,5),new THREE.MeshBasicMaterial({color,transparent:true}));m.position.copy(position);scene.add(m);effects.push({obj:m,vel:new THREE.Vector3((Math.random()-.5)*4,Math.random()*3,(Math.random()-.5)*4),life:.5+Math.random()*.25})}}
function makeRingEffect(pos,color=0x48eaff){const m=new THREE.Mesh(new THREE.TorusGeometry(.45,.065,8,28),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.9}));m.rotation.x=Math.PI/2;m.position.copy(pos);scene.add(m);effects.push({obj:m,life:.45,ring:true})}
function newRound(){if(player)world.remove(player);if(enemy)world.remove(enemy);projectiles.forEach(p=>scene.remove(p.obj));projectiles.length=0;player=createHero(heroChoice,'player');enemy=createHero(heroChoice==='volt'?'nova':'volt','enemy');player.position.set(-9,0,0);enemy.position.set(9,0,0);player.rotation.y=0;enemy.rotation.y=Math.PI;roundTime=120;ammo=24;reload=0;player.userData.health=200;enemy.userData.health=200;player.userData.ult=0;round++;updateHUD();}
function updateHUD(){if(!player||!enemy)return;const p=player.userData,e=enemy.userData;document.querySelector('#player-name').textContent=heroChoice.toUpperCase();document.querySelector('#enemy-name').textContent=(heroChoice==='volt'?'NOVA':'VOLT');document.querySelector('#player-health').style.width=`${Math.max(0,p.health)/p.maxHealth*100}%`;document.querySelector('#enemy-health').style.width=`${Math.max(0,e.health)/e.maxHealth*100}%`;document.querySelector('#player-health-text').textContent=`${Math.ceil(p.health)} / 200`;document.querySelector('#enemy-health-text').textContent=`${Math.ceil(e.health)} / 200`;document.querySelector('#player-ult').textContent=`${Math.floor(p.ult)}%`;document.querySelector('#player-score').textContent=scorePlayer;document.querySelector('#enemy-score').textContent=scoreEnemy;document.querySelector('#round-number').textContent=String(round).padStart(2,'0');document.querySelector('#ammo-count').textContent=ammo;document.querySelector('#ability-ult').classList.toggle('charged',p.ult>=100);document.querySelector('#ult-caption').textContent=p.ult>=100?'READY — Q':`${Math.floor(p.ult)}% CHARGED`;document.querySelector('#ability-dash').classList.toggle('cooling',p.dashWait>0);document.querySelector('#dash-caption').textContent=p.dashWait>0?`${p.dashWait.toFixed(1)} SEC`:'READY';document.querySelector('#ability-pulse').classList.toggle('cooling',p.pulseWait>0);document.querySelector('#pulse-caption').textContent=p.pulseWait>0?`${p.pulseWait.toFixed(1)} SEC`:'READY';}
function showToast(text){const el=document.querySelector('#center-toast');el.textContent=text;el.classList.add('show');toastTimer=1.15}
function feed(text,red=false){const line=document.createElement('div');line.className='kill-line'+(red?' red-line':'');line.textContent=text;const f=document.querySelector('#killfeed');f.prepend(line);while(f.children.length>3)f.lastChild.remove();setTimeout(()=>line.remove(),3300)}
function startGame(){document.querySelector('#start-screen').classList.add('hidden');document.querySelector('#pause-screen').classList.add('hidden');document.querySelector('#end-screen').classList.add('hidden');document.querySelector('#hud').classList.remove('hidden');mobile=('ontouchstart'in window)||navigator.maxTouchPoints>0;document.querySelector('#mobile-controls').classList.toggle('hidden',!mobile);scorePlayer=scoreEnemy=0;round=0;finished=false;paused=false;started=true;newRound();showToast('FIGHT!');canvas.focus?.()}
function pauseGame(){if(!started||finished)return;paused=!paused;document.querySelector('#pause-screen').classList.toggle('hidden',!paused)}
function endGame(won){finished=true;started=false;document.querySelector('#hud').classList.add('hidden');document.querySelector('#mobile-controls').classList.add('hidden');document.querySelector('#result-title').textContent=won?'VICTORY.':'DEFEAT.';document.querySelector('#result-title').style.color=won?'var(--cyan)':'var(--red)';document.querySelector('#result-kicker').textContent=won?'ARENA CHAMPION':'MATCH COMPLETE';document.querySelector('#result-copy').textContent=won?'The arena belongs to you. Clean work, legend.':'Your rival takes this round. Ready for the rematch?';document.querySelector('#end-screen').classList.remove('hidden')}
function hit(target,damage,source){const u=target.userData;u.health=Math.max(0,u.health-damage);u.hitFlash=.12;u.ult=Math.min(100,u.ult+(source==='player'?8:2));burst(target.position.clone().add(new THREE.Vector3(0,1.4,0)),source==='player'?0x65f4ff:0xff5472,6);if(source==='player'){document.querySelector('#hit-marker').classList.add('active');hitTimer=.12;player.userData.ult=Math.min(100,player.userData.ult+12)}updateHUD();if(u.health<=0&&u.alive){u.alive=false;const isPlayer=target===player;if(isPlayer)scoreEnemy++;else scorePlayer++;feed(isPlayer?'RIVAL  ×  YOU':`${heroChoice.toUpperCase()}  ×  ${enemy.userData.type.toUpperCase()}`,isPlayer);showToast(isPlayer?'ELIMINATED':'TAKEDOWN');burst(target.position.clone().add(new THREE.Vector3(0,1,0)),isPlayer?0xff5472:0x49e6f4,24);setTimeout(()=>{if(scorePlayer>=3||scoreEnemy>=3)endGame(scorePlayer>=3);else if(started){newRound();showToast('NEXT ROUND')}} ,1100)}}
function rayAim(){pointer.x=(lastPointer.x/window.innerWidth)*2-1;pointer.y=-(lastPointer.y/window.innerHeight)*2+1;raycaster.setFromCamera(pointer,camera);raycaster.ray.intersectPlane(floorPlane,aimPoint);aimPoint.x=THREE.MathUtils.clamp(aimPoint.x,-14,14);aimPoint.z=THREE.MathUtils.clamp(aimPoint.z,-12,12);return aimPoint}
let lastPointer={x:innerWidth/2,y:innerHeight/2};window.addEventListener('pointermove',e=>{lastPointer.x=e.clientX;lastPointer.y=e.clientY});
function firePlayer(ult=false){if(!player?.userData.alive||player.userData.fireWait>0||paused||!started)return;const p=player.userData;if(ult){if(p.ult<100)return;p.ult=0;ultTimer=2.2;showToast('OVERDRIVE');document.querySelector('#ability-ult').classList.add('charged');updateHUD() }else{if(reload>0)return;if(ammo<=0){reload=1.25;showToast('RELOADING');return}ammo--;document.querySelector('#ammo-count').textContent=ammo;reload=ammo===0?1.15:0}p.fireWait=ult?.095:.19;
 const origin=player.position.clone().add(new THREE.Vector3(0,1.33,0));const aim=rayAim(),dir=aim.sub(origin).normalize();if(dir.length()<.1)return;player.rotation.y=Math.atan2(dir.x,dir.z);player.userData.model.rotation.x=-.035;const dmg=ult?9:heroChoice==='nova'?27:22;makeProjectile(origin.add(dir.clone().multiplyScalar(.52)),dir,'player',dmg,ult?33:28);if(ult)for(let i=-2;i<=2;i++){const d=dir.clone().applyAxisAngle(new THREE.Vector3(0,1,0),i*.105);makeProjectile(origin.clone(),d,'player',9,32)}
}
function fireEnemy(){if(!enemy?.userData.alive||!player?.userData.alive)return;const e=enemy.userData;if(e.fireWait>0)return;e.fireWait=1.05+Math.random()*.45;const from=enemy.position.clone().add(new THREE.Vector3(0,1.35,0)),to=player.position.clone().add(new THREE.Vector3(0,1.15,0));const dir=to.sub(from);dir.x+=(Math.random()-.5)*1.3;dir.z+=(Math.random()-.5)*1.3;enemy.rotation.y=Math.atan2(dir.x,dir.z);makeProjectile(from,dir,'enemy',9,17)}
function useDash(){if(!started||paused||!player||player.userData.dashWait>0)return;const p=player.userData,move=getMove();let d=new THREE.Vector3(move.x,0,move.z);if(d.length()<.1){d=enemy.position.clone().sub(player.position);d.y=0;d.normalize()}player.position.add(d.multiplyScalar(3.2));player.position.x=THREE.MathUtils.clamp(player.position.x,-13,13);player.position.z=THREE.MathUtils.clamp(player.position.z,-11,11);p.dashWait=4;makeRingEffect(player.position.clone().add(new THREE.Vector3(0,.1,0)));burst(player.position.clone().add(new THREE.Vector3(0,.6,0)),0x4deeff,12);updateHUD()}
function usePulse(){if(!started||paused||!player||player.userData.pulseWait>0)return;player.userData.pulseWait=7;makeRingEffect(player.position.clone().add(new THREE.Vector3(0,.12,0)),0xffb75a);for(let i=0;i<16;i++){const angle=i/16*Math.PI*2;makeProjectile(player.position.clone().add(new THREE.Vector3(0,1,0)),new THREE.Vector3(Math.sin(angle),0,Math.cos(angle)),'player',16,15)}if(player.position.distanceTo(enemy.position)<5){enemy.userData.fireWait+=1.3;hit(enemy,22,'player')}updateHUD()}
function getMove(){let x=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+joy.x,z=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+joy.y;if(x||z){const v=new THREE.Vector3(x,0,z).normalize();return{x:v.x,z:v.z}}return{x:0,z:0}}
function update(dt){const now=clock.elapsedTime;if(!started||paused)return;roundTime-=dt;if(roundTime<=0){if(player.userData.health>=enemy.userData.health)scorePlayer++;else scoreEnemy++;if(scorePlayer>=3||scoreEnemy>=3)endGame(scorePlayer>=3);else{newRound();showToast('TIME — NEXT ROUND')}}
 const p=player.userData,e=enemy.userData;for(const u of [p,e]){u.fireWait=Math.max(0,u.fireWait-dt);u.dashWait=Math.max(0,u.dashWait-dt);u.pulseWait=Math.max(0,u.pulseWait-dt);u.hitFlash=Math.max(0,u.hitFlash-dt)}if(reload>0){reload-=dt;if(reload<=0){ammo=24;document.querySelector('#ammo-count').textContent=ammo}}if(ultTimer>0){ultTimer-=dt;if(fireHeld)firePlayer(true)}if(fireHeld&&ultTimer<=0)firePlayer(false);
 const mv=getMove();if(mv.x||mv.z){player.position.x+=mv.x*p.speed*dt;player.position.z+=mv.z*p.speed*dt;p.walk+=dt*12;p.model.position.y=Math.abs(Math.sin(p.walk))*.07;if(!fireHeld)player.rotation.y=Math.atan2(mv.x,mv.z)}else p.model.position.y*=.82;player.position.x=THREE.MathUtils.clamp(player.position.x,-13,13);player.position.z=THREE.MathUtils.clamp(player.position.z,-11,11);
 // Rival strafes, advances, seeks cover and fires intelligent bursts.
 const delta=player.position.clone().sub(enemy.position);delta.y=0;const dist=delta.length();if(dist>0){const d=delta.normalize();const side=new THREE.Vector3(-d.z,0,d.x);const strafe=Math.sin(now*.92)*.55;let speed=e.speed*(dist>8?1:.62);let vx=d.x*(dist>7?1:.2)+side.x*strafe,vz=d.z*(dist>7?1:.2)+side.z*strafe;const mag=Math.hypot(vx,vz)||1;enemy.position.x+=vx/mag*speed*dt;enemy.position.z+=vz/mag*speed*dt;enemy.rotation.y=Math.atan2(d.x,d.z);enemy.position.x=THREE.MathUtils.clamp(enemy.position.x,-12.5,12.5);enemy.position.z=THREE.MathUtils.clamp(enemy.position.z,-10.8,10.8);if(dist<17)fireEnemy();e.walk+=dt*9;e.model.position.y=Math.abs(Math.sin(e.walk))*.04}
 // Projectile collisions and bounds
 for(let i=projectiles.length-1;i>=0;i--){const b=projectiles[i];b.obj.position.addScaledVector(b.dir,b.speed*dt);b.life-=dt;let hitTarget=null;const target=b.team==='player'?enemy:player;if(target?.userData.alive){const d=b.obj.position.distanceTo(target.position.clone().add(new THREE.Vector3(0,1,0)));if(d<.78)hitTarget=target}if(hitTarget){hit(hitTarget,b.damage,b.team);scene.remove(b.obj);projectiles.splice(i,1)}else if(b.life<=0||Math.abs(b.obj.position.x)>17||Math.abs(b.obj.position.z)>15){scene.remove(b.obj);projectiles.splice(i,1)}}
 for(let i=effects.length-1;i>=0;i--){const fx=effects[i];fx.life-=dt;if(fx.ring){fx.obj.scale.setScalar(1+(0.5-fx.life)*5);fx.obj.material.opacity=Math.max(0,fx.life*2)}else{fx.obj.position.addScaledVector(fx.vel,dt);fx.vel.y-=5*dt;fx.obj.material.opacity=Math.max(0,fx.life*2)}if(fx.life<=0){scene.remove(fx.obj);effects.splice(i,1)}}
